def cite(key,label,fragment=''):
    return '<a class="inline-cite" href="'+SOURCES[key][1]+fragment+'" target="_blank" rel="noopener noreferrer">['+ESC(label)+']<span class="visually-hidden"> (fuente externa, abre en una pestaña nueva)</span></a>'
def sources(*keys):
    return '<section id="fuentes"><h2>Fuentes para seguir leyendo</h2><ul class="source-list">'+''.join(f'<li id="fuente-{k}"><a href="{SOURCES[k][1]}" target="_blank" rel="noopener noreferrer">{SOURCES[k][0]}<span class="visually-hidden"> (abre en una pestaña nueva)</span></a>'+('<span class="source-edition">'+ESC(SOURCE_EDITIONS[k])+'</span>' if k in SOURCE_EDITIONS else '')+'</li>' for k in keys)+'</ul><p class="text-muted"><small>Las referencias externas pertenecen a sus respectivas instituciones. Su inclusión no implica afiliación ni aval. Los textos internacionales se presentan como referencias académicas, no como legislación panameña.</small></p></section>'
EDITORIAL_REVIEWS=json.loads((ROOT/'content/editorial-reviews.json').read_text())['reviews']
def editorial_review(path):
    review=EDITORIAL_REVIEWS.get(path)
    if not review:return ''
    required=('reviewer','credential','reviewedOn','scope')
    if review.get('approved') is not True or review.get('humanReviewed') is not True or any(not review.get(k) for k in required):
        raise SystemExit('Editorial credit requires an approved, documented human review: '+path)
    reviewed=date.fromisoformat(review['reviewedOn'])
    if reviewed>date.today():raise SystemExit('Editorial review dates cannot be in the future.')
    return '<aside class="editorial-review" aria-label="Revisión editorial"><p><strong>Revisión editorial:</strong> '+ESC(review['reviewer'])+' · '+ESC(review['credential'])+'</p><p>Fecha: <time datetime="'+review['reviewedOn']+'">'+reviewed.strftime('%d/%m/%Y')+'</time>. '+ESC(review['scope'])+'</p></aside>'
FAQS=[
('¿Qué es la psicología forense?','Es la aplicación del conocimiento psicológico a cuestiones planteadas en contextos legales. En una evaluación forense, la pregunta que se busca responder y el uso previsto de los resultados delimitan el trabajo. <a href="/psicologia-forense/">Conoce los fundamentos</a>.'),
('¿Una evaluación forense es lo mismo que una terapia?','Son procesos con finalidades diferentes. La terapia se orienta a las necesidades de atención de una persona; la evaluación forense responde a una cuestión definida en un contexto legal. Es importante aclarar el rol profesional desde el inicio.'),
('¿Dónde encuentro legislación y documentos judiciales de Panamá?','El <a href="https://www.organojudicial.gob.pa/cendoj" target="_blank" rel="noopener noreferrer">Centro de Documentación Judicial del Órgano Judicial de Panamá<span class="visually-hidden"> (abre en una pestaña nueva)</span></a> ofrece acceso a información jurídica. También puedes visitar nuestra selección de <a href="/recursos/">fuentes institucionales</a>.'),
('¿Puedo enviar información de un caso por este sitio?','Este sitio no recibe expedientes, evaluaciones, denuncias ni datos de pacientes. Evita compartir información sensible. Para un asunto particular, identifica el canal autorizado de la entidad o del profesional que corresponda.'),
('¿Cómo puedo contactar a APAPSIF o solicitar afiliación?','Consulta el correo y el perfil público de APAPSIF en nuestra página de <a href="/contacto/">contacto</a>. Puedes preguntar directamente por los requisitos y el procedimiento de afiliación. Este sitio no procesa inscripciones ni pagos.')]
FAQS=[(q,a+(' '+cite('apa','APA, 2013, p. 7','#page=1') if i==0 else ' '+cite('roles','Subijana y Echeburúa, 2022') if i==1 else '')) for i,(q,a) in enumerate(FAQS)]
def faqs(items=FAQS):
    return '<div class="faq-list">'+''.join(f'<details class="faq-item"><summary>{q}</summary><div class="faq-answer">{a}</div></details>' for q,a in items)+'</div>'
NAV=[('Inicio','/'),('La asociación','/asociacion/'),('Psicología forense','/psicologia-forense/'),('Recursos','/recursos/'),('Contacto','/contacto/')]
PAGES=[]
def register(path,title,description,body,section=None,article=False,keywords='',schema=None):
    PAGES.append(dict(path=path,title=title,description=description,body=body,section=section or path,article=article,keywords=keywords,schema=schema))
def hero(title,desc,label='APAPSIF · Panamá',crumb=None,extra=''):
    breadcrumb='<nav class="breadcrumb" aria-label="Ruta de navegación"><a href="/">Inicio</a><span aria-hidden="true">/</span>'
    if crumb:breadcrumb+=f'<a href="{crumb[1]}">{crumb[0]}</a><span aria-hidden="true">/</span>'
    breadcrumb+=f'<span aria-current="page">{ESC(re.sub("<[^>]+>"," ",title))}</span></nav>'
    heading=title.replace('<br>',' ')
    return f'<section class="page-hero"><div class="container">{breadcrumb}<p class="eyebrow">{label}</p><h1>{heading}</h1><p class="lede">{desc}</p>{extra}</div></section>'
def article_wrap(content,items):
    return '<section class="section"><div class="container content-sidebar"><nav class="side-nav" aria-label="En esta página"><p>En esta página</p>'+''.join(f'<a href="#{id}">{label}</a>' for id,label in items)+'</nav><div class="article">'+content+'</div></div></section>'
def cta():return f'<section class="end-cta"><div class="container"><div><h2>Biblioteca de psicología forense.</h2><p>Consulta conceptos, preguntas frecuentes y referencias identificadas.</p></div>{link("Explorar recursos","/recursos/","button")}</div></section>'
HOME=f'''<section class="home-hero"><div class="container hero-grid"><div class="hero-copy"><p class="eyebrow">APAPSIF · Panamá</p><h1>Psicología forense<br><em>en Panamá.</em></h1><p class="lede">Asociación Panameña de Psicología Forense. Un espacio para conocer la disciplina, consultar fuentes y conectar con la asociación.</p><div class="hero-actions">{link('Conoce la asociación','/asociacion/','button')}{link('Explorar recursos','/recursos/','text-link')}</div><p class="hero-footnote">Conocimiento psicológico. Contexto jurídico. Perspectiva humana.</p></div><div class="hero-emblem" aria-hidden="true"><div class="emblem-orbit orbit-one"></div><div class="emblem-orbit orbit-two"></div><span class="emblem-psi">Ψ</span><span class="emblem-rule"></span><div class="emblem-caption"><span>PSICOLOGÍA</span><span>JUSTICIA</span></div><span class="emblem-place">PANAMÁ · APAPSIF</span></div></div></section>
<section class="pathways" aria-labelledby="pathways-title"><div class="container"><div class="pathways-heading"><h2 id="pathways-title">¿Por dónde quieres empezar?</h2><p>Encuentra lo que necesitas.</p></div><div class="pathways-grid"><a class="pathway" href="/psicologia-forense/"><span class="pathway-number">01 / COMPRENDER</span><h3>Conoce la psicología forense</h3><p>Qué estudia, cómo se diferencia de la terapia y por qué importa su contexto.</p><span class="pathway-action">Leer la introducción {ARROW}</span></a><a class="pathway" href="/recursos/"><span class="pathway-number">02 / CONSULTAR</span><h3>Encuentra una referencia</h3><p>Guías, conceptos y fuentes académicas e institucionales, en un solo lugar.</p><span class="pathway-action">Abrir la biblioteca {ARROW}</span></a><a class="pathway" href="/contacto/"><span class="pathway-number">03 / CONECTAR</span><h3>Acércate a APAPSIF</h3><p>Consulta sobre la asociación, sus actividades o el proceso de afiliación.</p><span class="pathway-action">Ver canales de contacto {ARROW}</span></a></div></div></section>
<section class="section home-association"><div class="container split"><div><p class="eyebrow">La asociación</p><h2>La psicología forense,<br>desde Panamá.</h2></div><div><p class="lede">La Asociación Panameña de Psicología Forense (APAPSIF) cuenta con participación documentada en espacios de diálogo institucional en Panamá.</p><p class="mt-24">En 2022, el IMELCF registró su participación en una mesa de trabajo sobre propuestas de modificación de las leyes 50 y 69. Una referencia concreta para conocer su trayectoria.</p>{link('Conocer nuestra historia','/asociacion/','text-link mt-24')}<p class="source-caption">Registro institucional: {cite('imelcf2022','IMELCF · septiembre de 2022')}</p></div></div></section>
<section class="section home-foundations"><div class="container split"><div><p class="eyebrow">Una distinción esencial</p><h2>Evaluar y acompañar.<br><em>Dos propósitos distintos.</em></h2><p class="lede mt-24">Comprender la finalidad de cada proceso ayuda a entender el papel del profesional.</p>{link('Profundizar en los fundamentos','/psicologia-forense/','text-link mt-24')}</div><div class="purpose-comparison"><article><p class="mini-label">Contexto legal</p><h3>Evaluación forense</h3><p>Responde a una pregunta psicológica delimitada en un contexto legal.</p></article><article><p class="mini-label">Atención y bienestar</p><h3>Terapia</h3><p>Se orienta a las necesidades de atención de una persona.</p></article><p class="comparison-source">Referencia: {cite('roles','Subijana y Echeburúa, 2022')}</p></div></div></section>
<section class="section home-library"><div class="container"><div class="section-head"><div><p class="eyebrow">Biblioteca abierta</p><h2>Una buena pregunta<br>merece una buena fuente.</h2></div>{link('Ver todos los recursos','/recursos/')}</div><div class="featured-resources"><a href="/recursos/glosario/" class="featured-resource"><span class="tag">Conceptos · Español</span><h3>Las palabras de la psicología forense.</h3><p>Ocho términos esenciales, con explicaciones breves y referencias.</p><span class="pathway-action">Explorar el glosario {ARROW}</span></a><a href="/recursos/?categoria=institucionales" class="featured-resource"><span class="tag">Fuentes · Panamá</span><h3>Información en su contexto original.</h3><p>Accede a publicaciones del IMELCF y del Órgano Judicial de Panamá.</p><span class="pathway-action">Consultar fuentes {ARROW}</span></a><a href="/recursos/?categoria=academicos" class="featured-resource"><span class="tag">Lecturas · Investigación</span><h3>Profundiza en la práctica y sus límites.</h3><p>Referencias académicas sobre la evaluación, los roles y la ética profesional.</p><span class="pathway-action">Ver lecturas académicas {ARROW}</span></a></div></div></section>
<section class="section home-faq"><div class="container split"><div><p class="eyebrow">Preguntas frecuentes</p><h2>Empecemos<br>por lo esencial.</h2>{link('Ver todas las respuestas','/recursos/preguntas-frecuentes/','text-link mt-24')}</div><div>{faqs(FAQS[:3])}</div></div></section>
<section class="contact-band"><div class="container"><div><p class="eyebrow">Conecta con APAPSIF</p><h2>El siguiente paso<br>empieza con una consulta.</h2><p>Información institucional, actividades y afiliación.</p></div>{link('Contactar a la asociación','/contacto/','button')}</div></section>'''
register('/','Psicología forense en Panamá | APAPSIF','Conoce APAPSIF, la Asociación Panameña de Psicología Forense. Explora recursos en español, evaluación forense, fuentes de Panamá y contacto para afiliación.',HOME,keywords='panama asociación psicología justicia inicio')
ASSOC=hero('La asociación.','Identidad de APAPSIF y una referencia documentada de su participación institucional en Panamá.',label='Identidad · APAPSIF')+article_wrap(f'''<section id="identidad"><h2>Asociación Panameña<br>de Psicología Forense</h2><p class="lede">APAPSIF es la sigla de la Asociación Panameña de Psicología Forense, denominación recogida en una publicación institucional del IMELCF. {cite('imelcf2022','IMELCF, 2022')}</p><p>Este espacio acerca la psicología forense a profesionales, estudiantes y personas interesadas en su relación con la justicia. Aquí encontrarás una introducción a la disciplina, fuentes para profundizar y canales para contactar a la asociación.</p></section><section id="trayectoria"><h2>Una referencia de su trayectoria</h2><div class="timeline"><article class="timeline-item"><span class="tag">29 de septiembre de 2022</span><h3>Participación en una mesa de trabajo del IMELCF</h3><p>Una nota del Instituto de Medicina Legal y Ciencias Forenses registra a APAPSIF entre las asociaciones participantes en una reunión sobre propuestas de modificación de las leyes 50 y 69. La publicación identifica a Indira Gordón como su representante en ese encuentro. {cite('imelcf2022','IMELCF, 2022')}</p>{link('Leer la reseña documentada','/actualidad/mesa-trabajo-imelcf-2022/')}</article></div><p><small>Esta referencia describe una participación histórica. No establece quiénes ocupan actualmente cargos directivos ni acredita servicios, convenios o representación vigente.</small></p></section><section id="sitio"><h2>Cómo explorar este espacio</h2><ol class="numbered-steps"><li><strong>Conoce la disciplina</strong>Empieza con una explicación de qué es la psicología forense y cuáles son algunas preguntas habituales.</li><li><strong>Consulta fuentes identificadas</strong>La biblioteca distingue los contenidos introductorios de los recursos externos y enlaza a sus instituciones de origen.</li><li><strong>Revisa el estado del contacto</strong>Consulta los canales publicados por APAPSIF y pregunta por actividades o afiliación. Este sitio no recibe información de casos.</li></ol>{link('Explorar la biblioteca','/recursos/','button')}</section>{sources('imelcf2022')}''',[('identidad','Identidad'),('trayectoria','Trayectoria'),('sitio','Acerca del sitio'),('fuentes','Fuente institucional')])+cta()
register('/asociacion/','La asociación | APAPSIF Panamá','Conoce la identidad de APAPSIF, Asociación Panameña de Psicología Forense, y su participación documentada en una mesa de trabajo del IMELCF.',ASSOC,keywords='asociacion identidad historia misión afiliación junta directiva')
FORENSIC=hero('Psicología forense,<br>con claridad.','Una introducción al encuentro entre el conocimiento psicológico y las preguntas que surgen en el ámbito de la justicia.',label='Comprender · Fundamentos')+article_wrap(f'''<section id="que-es"><h2>¿Qué es la psicología forense?</h2><p class="lede">La psicología forense aplica conocimientos científicos, técnicos y especializados de la psicología a cuestiones que surgen en contextos judiciales, administrativos y legales. {cite('apa','APA, 2013, p. 7','#page=1')}</p><p>La finalidad del trabajo importa: una evaluación se organiza alrededor de una pregunta concreta. Comprender ese encargo ayuda a situar el alcance de las conclusiones y el contexto en el que se utilizarán.</p></section><section id="evaluacion"><h2>Evaluación y terapia:<br>finalidades diferentes</h2><p>Una evaluación forense responde a una pregunta delimitada en un contexto legal. La terapia busca atender necesidades de salud y bienestar. Son funciones distintas; combinarlas puede generar conflictos de rol y afectar la objetividad. {cite('roles','Subijana y Echeburúa, 2022')}</p><p>La literatura académica sobre prueba pericial examina estas diferencias y los problemas que aparecen cuando se confunden las funciones clínica y forense. Por eso, conocer el propósito del encuentro y el papel del profesional es un primer paso importante.</p><div class="notice"><strong>Una pregunta útil antes de comenzar</strong>¿Cuál es la finalidad de este proceso, quién solicita la evaluación y cómo se utilizará la información?</div></section><section id="etica"><h2>Claridad, responsabilidad<br>y límites</h2><p>Antes de una evaluación, es importante conocer su finalidad, el uso previsto de la información, quién podrá recibir los resultados y los límites de la confidencialidad. El alcance concreto depende del encargo y de la normativa aplicable. {cite('apa','APA, 2013, §6.03','#page=6')}</p><p>Las referencias que acompañan esta página permiten profundizar en estos temas. Las guías internacionales se presentan como material académico identificado por su fecha, y no como reglas de APAPSIF ni como normativa vigente en Panamá.</p></section><section id="panama"><h2>Una mirada desde Panamá</h2><p>En febrero de 2026, el IMELCF publicó una nota sobre el aporte de la psicología forense al acceso a la justicia. Entre los temas abordados se encuentran el daño psicológico, el trauma y los protocolos de evaluación. {cite('imelcf2026','IMELCF, 2026')}</p><p>La publicación ofrece un punto de partida local para conocer el campo. Es una actividad del IMELCF; su inclusión aquí no la convierte en un evento organizado por APAPSIF.</p>{link('Leer la publicación del IMELCF',SOURCES['imelcf2026'][1],'text-link mt-24',True)}</section><section id="alcance"><h2>El alcance de esta introducción</h2><p>Este contenido es informativo. No es una evaluación individual, una opinión pericial ni asesoría jurídica o psicológica. Un asunto particular requiere revisar sus circunstancias con profesionales y canales autorizados.</p><div class="inline-cta"><p>¿Encontraste un término nuevo?<br>Consulta el glosario introductorio.</p>{link('Abrir glosario','/recursos/glosario/','button outline')}</div></section>{sources('apa','roles','imelcf2026')}''',[('que-es','Qué es'),('evaluacion','Evaluación y terapia'),('etica','Ética y límites'),('panama','Contexto panameño'),('alcance','Alcance del contenido'),('fuentes','Referencias')])+cta()
register('/psicologia-forense/','Qué es la psicología forense | APAPSIF Panamá','Introducción a la psicología forense: finalidad de la evaluación, diferencias con la terapia, límites de la información y fuentes para profundizar.',FORENSIC,article=True,keywords='psicologia forense peritaje evaluación ética confidencialidad terapia ciencia daño psicológico')
RESOURCES=[
('Guía introductoria','Qué es la psicología forense','Empieza por la finalidad de la evaluación, el rol profesional y el contexto en el que se utiliza la información.','/psicologia-forense/','guides',False),
('Glosario interactivo','Ocho conceptos esenciales','Busca términos y filtra por fundamentos, práctica o ética. Definiciones breves para una primera lectura.','/recursos/glosario/','guides',False),
('Preguntas frecuentes','Una orientación inicial','Respuestas sobre la disciplina, el alcance de esta web y el estado de los canales de contacto.','/recursos/preguntas-frecuentes/','guides',False),
('Órgano Judicial de Panamá','Centro de Documentación Judicial','Consulta información jurídica, legislación y jurisprudencia en el portal institucional del CENDOJ.',SOURCES['cendoj'][1],'official',True),
('Órgano Judicial de Panamá','Registro Judicial','Accede al repositorio institucional del Registro Judicial para consultar sus publicaciones.',SOURCES['registro'][1],'official',True),
('IMELCF · 2026','Psicología forense y acceso a la justicia','Una publicación institucional sobre el campo, el daño psicológico, el trauma y la práctica forense.',SOURCES['imelcf2026'][1],'official',True),
('Referencia académica · 2022','Los límites entre el rol clínico y el forense','Artículo de Subijana y Echeburúa, publicado en Anuario de Psicología Jurídica, 32(1), 107–114. Su contexto jurídico es español.',SOURCES['roles'][1],'academic',True),
('Referencia académica · 2013','Guías especializadas de psicología forense','Documento de la American Psychological Association, en inglés. Referencia histórica; no se presenta como normativa vigente.',SOURCES['apa'][1],'academic',True)]
RESOURCE_METADATA=json.loads((ROOT/'content/resources.json').read_text())
def resource_metadata(url,external):
    item=RESOURCE_METADATA[url]
    date=(f'<time datetime="{item["published"]}">{item["dateLabel"]}</time>' if item['published'] else 'Sin fecha indicada')
    fields=[('Formato',ESC(item['format'])),('Idioma',ESC(item['language'])),('Publicación',date),('Ubicación','Fuente externa' if external else 'En este sitio')]
    return '<ul class="resource-meta" aria-label="Datos del recurso">'+''.join(f'<li><span class="visually-hidden">{label}: </span>{value}</li>' for label,value in fields)+'</ul>'+('<p class="resource-edition"><strong>Edición consultada:</strong> '+ESC(item['edition'])+'</p>' if item.get('edition') else '')
def resource_link(title,url,external):
    action='Abrir PDF' if RESOURCE_METADATA[url]['format']=='PDF' else ('Visitar fuente' if external else 'Explorar recurso')
    label=action+'<span class="visually-hidden">: '+ESC(title)+'</span>'
    return link(label,url,'text-link',external)
def filters(labels,categories):
    return '<div class="filter-bar js-only" role="group" aria-label="Filtrar por categoría">'+''.join(f'<button class="filter-button" type="button" data-filter="{k}" data-filter-label="{v}" aria-label="{v}: {len(categories) if k=="all" else categories.count(k)} resultados" aria-pressed="{str(i==0).lower()}">{v} <span class="filter-tally" aria-hidden="true">{len(categories) if k=="all" else categories.count(k)}</span></button>' for i,(k,v) in enumerate(labels))+'</div>'
def filter_toolbar(label):
    return '<div class="directory-toolbar"><p class="result-count" id="filter-count" role="status" aria-live="polite">8 '+label+'</p><div class="filter-tools js-only"><button class="text-link reset-filters" type="button" data-reset-filter>Limpiar filtros</button><span class="copy-feedback" id="copy-message" role="status" aria-live="polite"></span><button class="text-link" type="button" data-copy-link>Copiar esta vista '+ARROW+'</button></div></div>'
