CONTACT=hero('Conversemos.','Contacta a APAPSIF para información institucional, actividades o consultas sobre afiliación.',label='Contacto · APAPSIF')+f'''<section class="section contact-section"><div class="container"><div class="contact-grid"><article class="contact-primary"><p class="eyebrow">Correo de contacto</p><h2>Escribe a<br>la asociación.</h2><a class="contact-email" href="mailto:apapsif.panama@gmail.com">apapsif.panama@gmail.com</a><p>Incluye tu nombre y el motivo de tu consulta. Para información sobre afiliación, solicita los requisitos y el procedimiento directamente a APAPSIF.</p><div class="contact-actions">{link('Abrir mi correo','mailto:apapsif.panama@gmail.com?subject=Consulta%20a%20APAPSIF','button')}<button class="text-link js-only" type="button" data-copy-email>Copiar correo {ARROW}</button></div><p id="email-copy-status" class="copy-message" role="status" aria-live="polite"></p><p class="contact-source">Dirección publicada en el perfil <a href="https://www.instagram.com/apapsif/" target="_blank" rel="noopener noreferrer">@apapsif en Instagram<span class="visually-hidden"> (abre en una pestaña nueva)</span></a>.</p></article><aside class="contact-secondary" aria-labelledby="contact-topics"><h2 id="contact-topics">¿En qué podemos orientarte?</h2><ul class="contact-topics"><li><span>01</span><div><h3>La asociación</h3><p>Información institucional y canales de participación.</p></div></li><li><span>02</span><div><h3>Afiliación</h3><p>Consulta los requisitos y pasos para solicitar tu ingreso.</p></div></li><li><span>03</span><div><h3>Actividades</h3><p>Pregunta por encuentros, formación y novedades.</p></div></li></ul>{link('Visitar @apapsif','https://www.instagram.com/apapsif/','text-link',True)}</aside></div><div class="contact-safety"><p><strong>Para consultas generales.</strong> Evita incluir expedientes, documentos de identidad, informes o datos sensibles. Este sitio no procesa solicitudes de atención, inscripciones ni pagos.</p><a href="/privacidad/">Consultar privacidad</a></div></div></section>'''
register('/contacto/','Contacto y afiliación | APAPSIF Panamá','Encuentra el correo de contacto y el perfil público de APAPSIF. Consulta información sobre la asociación, actividades y el procedimiento de afiliación.',CONTACT,keywords='contacto correo teléfono email dirección afiliación inscripción miembro instagram apapsif.panama@gmail.com')
NEWS=hero('APAPSIF en una<br>mesa de trabajo<br>del IMELCF.','Una referencia documentada de participación institucional en Panamá.',label='Archivo · Participación institucional',crumb=('La asociación','/asociacion/'),extra='<div class="meta"><span>Encuentro: 29 de septiembre de 2022</span><span>Fuente: IMELCF</span></div>')+article_wrap(f'''<section id="encuentro"><h2>Un encuentro de trabajo interdisciplinario</h2><p class="lede">El 29 de septiembre de 2022, APAPSIF participó, representada por Indira Gordón, en una mesa de trabajo convocada por el Instituto de Medicina Legal y Ciencias Forenses. {cite('imelcf2022','IMELCF, 2022')}</p><p>Según la nota publicada por el IMELCF el 30 de septiembre de 2022, el encuentro abordó propuestas de modificación de las leyes 50 y 69 y reunió a representantes de asociaciones vinculadas al ámbito forense.</p><p>La publicación institucional menciona a la Asociación Panameña de Psicología Forense por su nombre y sigla. Esta reseña permite acceder a ese registro público desde el sitio de APAPSIF.</p></section><section id="contexto"><h2>Cómo interpretar esta referencia</h2><p>Se trata de un hecho histórico. La mención de una representante en esa reunión no permite inferir cargos directivos actuales, convenios vigentes ni servicios de la asociación.</p><p>Para consultar el contexto completo, utiliza la publicación original del IMELCF.</p>{link('Leer la publicación original',SOURCES['imelcf2022'][1],'button mt-24',True)}</section>{sources('imelcf2022')}<div class="article-actions"><button class="button outline js-only" type="button" data-copy-link>Copiar enlace {ARROW}</button><button class="button outline js-only" type="button" data-print>Imprimir reseña {ARROW}</button></div><p id="copy-message" class="copy-message" role="status" aria-live="polite"></p>''',[('encuentro','El encuentro'),('contexto','Contexto de la reseña'),('fuentes','Fuente original')])+cta()
register('/actualidad/mesa-trabajo-imelcf-2022/','APAPSIF en la mesa de trabajo del IMELCF de 2022','Referencia documentada de la participación de APAPSIF en la mesa de trabajo del IMELCF del 29 de septiembre de 2022 sobre propuestas para las leyes 50 y 69.',NEWS,section='/asociacion/',article=True,keywords='noticia actualidad archivo imelf 2022 Indira Gordón mesa trabajo leyes')
PRIV=hero('Privacidad y uso<br>de la información.','Cómo funcionan la búsqueda, los enlaces y los canales de contacto de este sitio.',label='Transparencia · Privacidad')+article_wrap('''<section id="datos"><h2>Datos que solicita este sitio</h2><p>Este sitio no contiene formularios de contacto o afiliación, no solicita cuentas propias y no acepta pagos, expedientes ni archivos. Los enlaces de correo abren la aplicación de correo de tu dispositivo; el sitio no envía el mensaje por ti. No incluyas datos sensibles en consultas generales.</p><p>La búsqueda general del sitio funciona en tu navegador. En la biblioteca y el glosario, los términos y la categoría se incluyen en la dirección de la página para compartir la vista y recuperarla al volver. Pueden permanecer en el historial del navegador; si abres o compartes ese enlace, su dirección también puede formar parte de los registros técnicos del alojamiento. Usa términos generales y evita información personal o de casos.</p></section><section id="tecnologia"><h2>Alojamiento y funciones del navegador</h2><p>El sitio se aloja en __HOSTING_PROVIDER__. El proveedor puede procesar información técnica necesaria para servir las páginas, conforme a sus condiciones y políticas.</p><p>Esta implementación no incorpora herramientas propias de publicidad, analítica de terceros ni cookies de seguimiento. Los mecanismos de acceso del proveedor de alojamiento pueden operar de forma independiente.</p><p>La función “Copiar enlace” utiliza el portapapeles de tu navegador cuando la activas. La impresión se realiza a través del cuadro de diálogo de tu dispositivo.</p></section><section id="externos"><h2>Enlaces a otros sitios</h2><p>Los recursos externos se abren en una pestaña nueva y pertenecen a otras instituciones o autores. Al visitarlos, se aplican sus propias políticas y condiciones. No se incrustan vídeos, mapas ni herramientas de redes sociales en esta versión.</p></section><section id="revision"><h2>Contacto y futuras funciones</h2><p>La dirección de contacto se reproduce del perfil público de APAPSIF. El contenido de cualquier correo que decidas enviar se gestiona fuera de este sitio. Si se incorporan formularios o nuevas funciones de recepción de datos, se actualizará esta información antes de activarlos.</p><p>Evita introducir información personal sensible en términos de búsqueda o al navegar hacia servicios externos.</p></section>''',[('datos','Datos solicitados'),('tecnologia','Tecnología y alojamiento'),('externos','Enlaces externos'),('revision','Revisión institucional')])
register('/privacidad/','Privacidad y uso de la información | APAPSIF','Conoce cómo funcionan la búsqueda, los enlaces de correo y el uso de información en APAPSIF. Sin formularios, pagos ni herramientas propias de seguimiento.',PRIV,keywords='privacidad datos cookies información personal')
LEGAL=hero('Información y<br>alcance del sitio.','El contexto importa. Aquí explicamos cómo leer y utilizar este contenido.',label='Transparencia · Aviso informativo')+article_wrap('''<section id="alcance"><h2>Contenido introductorio</h2><p>La información de este sitio tiene fines educativos y de orientación general. No constituye asesoría legal, atención psicológica, evaluación, diagnóstico ni opinión pericial para una persona o un caso concreto.</p><p>El contenido no debe utilizarse como sustituto de una consulta profesional ni como medio para presentar una denuncia o solicitar atención urgente.</p></section><section id="institucion"><h2>Información institucional</h2><p>APAPSIF corresponde a la Asociación Panameña de Psicología Forense. El nombre y el emblema se utilizan en esta propuesta de sitio. Los datos institucionales pendientes de confirmación se identifican expresamente.</p><p>No se atribuyen a la asociación servicios, certificaciones, convenios, cargos actuales ni requisitos de afiliación que no hayan sido verificados.</p></section><section id="fuentes"><h2>Fuentes y referencias</h2><p>Las notas históricas enlazan a sus fuentes originales. Las publicaciones académicas internacionales se identifican por autor o institución y por fecha; no se presentan como normas panameñas.</p><p>Los enlaces externos se incluyen para facilitar la consulta. Su presencia no significa que exista afiliación, representación, convenio o respaldo entre APAPSIF y la institución enlazada.</p></section><section id="version"><h2>Estado de esta versión</h2><p>Esta es una vista previa privada para revisión. El dominio apapsif.com todavía no está conectado. Los enlaces de contacto abren canales externos a este sitio.</p><p>La información y las funciones descritas corresponden a esta versión. Una nueva función que reciba datos requerirá revisar los avisos y condiciones aplicables antes de activarse.</p></section>''',[('alcance','Alcance educativo'),('institucion','Información institucional'),('fuentes','Fuentes y enlaces'),('version','Estado de la versión')])
register('/aviso-informativo/','Aviso informativo y alcance | APAPSIF','Información sobre el alcance educativo de los contenidos, las fuentes externas y el estado de revisión de este sitio de APAPSIF.',LEGAL,keywords='aviso informativo legal alcance educativo')
register('/404.html','Página no encontrada | APAPSIF','La página que buscas no está disponible. Regresa al inicio o explora los recursos de APAPSIF.',f'<section class="error-page"><div class="container"><p class="eyebrow">Error 404</p><h1>Volvamos a<br>un buen punto de partida.</h1><p class="lede">No encontramos esta página. Puedes ir al inicio o buscar en la biblioteca.</p>{link("Ir al inicio","/","button")} <span aria-hidden="true">&nbsp;</span> {link("Explorar recursos","/recursos/","button outline")}</div></section>')

def nav(section,mobile=False):return ''.join(f'<a href="{url}"'+(' aria-current="page"' if url==section else '')+(' class="nav-contact"' if url=='/contacto/' else '')+f'>{label}</a>' for label,url in NAV)
def document(page):
    path=page['path']; url=ORIGIN+path; title=page['title']; desc=page['description']
    data=[{'@context':'https://schema.org','@type':'Organization','@id':ORIGIN+'/#organization','name':CONFIG['organization'],'alternateName':'APAPSIF','url':ORIGIN+'/','logo':{'@type':'ImageObject','url':ORIGIN+'/assets/apapsif-logo.jpg','width':2048,'height':659}}, {'@context':'https://schema.org','@type':'WebSite','@id':ORIGIN+'/#website','name':'APAPSIF','url':ORIGIN+'/','inLanguage':'es-PA','publisher':{'@id':ORIGIN+'/#organization'}}, {'@context':'https://schema.org','@type':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':desc,'inLanguage':'es-PA','isPartOf':{'@id':ORIGIN+'/#website'}}]
    if path not in ['/','/404.html']:
        crumbs=[{'@type':'ListItem','position':1,'name':'Inicio','item':ORIGIN+'/'}]
        if path.startswith('/recursos/') and path!='/recursos/':crumbs.append({'@type':'ListItem','position':2,'name':'Recursos','item':ORIGIN+'/recursos/'})
        crumbs.append({'@type':'ListItem','position':len(crumbs)+1,'name':title.split(' | ')[0],'item':url})
        data.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':crumbs})
    search_data=[dict(title=p['title'].split(' | ')[0],description=p['description'],url=BASE_PATH+p['path'],keywords=p['keywords']) for p in PAGES if p['path']!='/404.html']
    search_data += [dict(title=t,description=d,url=BASE_PATH+'/recursos/glosario/#'+slug(t),keywords='glosario '+CAT[c],kind='Concepto') for t,c,d in GLOSSARY]
    search_data += [dict(title=t,description=d,url=u,keywords=tag+' '+RESOURCE_METADATA[u]['format'],kind='Fuente externa') for tag,t,d,u,c,e in RESOURCES if e]
    search_json=json.dumps(search_data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    reading_minutes=max(1,round(len(re.sub('<[^>]+>',' ',page['body']).split())/200))
    if page['article']:
        page['body']=page['body'].replace('<div class="meta">','<div class="meta"><span>'+str(reading_minutes)+' min de lectura</span>',1) if '<div class="meta">' in page['body'] else page['body'].replace('</h1>','</h1><p class="reading-time">'+str(reading_minutes)+' min de lectura · Con fuentes de consulta</p>',1)
    preview='<div class="preview-bar">Vista previa privada<span aria-hidden="true">·</span>APAPSIF</div>' if PREVIEW else ''
    robots='noindex, nofollow, noarchive' if PREVIEW or path=='/404.html' else 'index, follow, max-image-preview:large'
    return f'''<!doctype html>
<html lang="es-PA" data-base-path="{BASE_PATH}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{ESC(title)}</title><meta name="description" content="{ESC(desc,quote=True)}"><meta name="robots" content="{robots}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#143d50"><meta property="og:type" content="website"><meta property="og:site_name" content="APAPSIF"><meta property="og:title" content="{ESC(title,quote=True)}"><meta property="og:description" content="{ESC(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:locale" content="es_PA"><meta property="og:image" content="{ORIGIN}/assets/apapsif-logo.jpg"><meta property="og:image:alt" content="Emblema de APAPSIF, Asociación Panameña de Psicología Forense"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{ESC(title,quote=True)}"><meta name="twitter:description" content="{ESC(desc,quote=True)}"><meta name="twitter:image" content="{ORIGIN}/assets/apapsif-logo.jpg"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css?v={CSS_HASH}"><script src="/assets/site.js?v={JS_HASH}" defer></script><script type="application/ld+json">{json.dumps(data,ensure_ascii=False,separators=(',',':'))}</script></head>
<body{' data-article="true"' if page['article'] else ''}><a class="skip-link" href="#main">Saltar al contenido</a>{preview}<header class="site-header"><div class="container header-inner"><a class="brand" href="/" aria-label="APAPSIF, ir al inicio"><img src="/assets/apapsif-logo.jpg" alt="APAPSIF · Asociación Panameña de Psicología Forense" width="2048" height="659" fetchpriority="high"></a><nav class="desktop-nav" aria-label="Navegación principal">{nav(page['section'])}</nav><div class="header-actions"><button class="icon-button js-only" type="button" data-open-search aria-label="Buscar en el sitio" aria-haspopup="dialog">{SEARCH}</button><button class="icon-button menu-toggle js-only" type="button" data-menu-toggle aria-label="Abrir menú" aria-expanded="false" aria-controls="mobile-navigation"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 7h14M5 12h14M5 17h14"/></svg></button></div></div><nav class="mobile-nav" id="mobile-navigation" aria-label="Navegación móvil">{nav(page['section'],True)}</nav><div class="reading-progress" aria-hidden="true"></div></header><main id="main" class="page-main" tabindex="-1">{page['body']}{editorial_review(path)}</main>
<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-brand"><a href="/" aria-label="APAPSIF, inicio"><img src="/assets/apapsif-logo.jpg" alt="APAPSIF · Asociación Panameña de Psicología Forense" width="2048" height="659" loading="lazy"></a><p>Asociación Panameña de Psicología Forense.<br>Conceptos y fuentes de consulta en español.</p></div><div class="footer-column"><h2>Explora</h2><a href="/asociacion/">La asociación</a><a href="/psicologia-forense/">Psicología forense</a><a href="/recursos/">Biblioteca de recursos</a><a href="/contacto/">Contacto y afiliación</a></div><div class="footer-column"><h2>Para empezar</h2><a href="/recursos/glosario/">Glosario introductorio</a><a href="/recursos/preguntas-frecuentes/">Preguntas frecuentes</a><a href="/actualidad/mesa-trabajo-imelcf-2022/">Referencia histórica</a><a href="https://www.instagram.com/apapsif/" target="_blank" rel="noopener noreferrer">Instagram · @apapsif<span class="visually-hidden"> (abre en una pestaña nueva)</span></a></div></div><div class="footer-bottom"><p>© 2026 APAPSIF · Asociación Panameña de Psicología Forense</p><div><a href="/privacidad/">Privacidad</a><a href="/aviso-informativo/">Aviso informativo</a><a href="/recursos/">Explorar recursos</a></div></div>{'<p class="draft-note">Vista previa para revisión. El dominio apapsif.com aún no está conectado. Los contenidos introductorios no sustituyen asesoría profesional.</p>' if PREVIEW else ''}</div></footer>
<dialog class="search-dialog" id="site-search" aria-labelledby="search-title"><div class="search-dialog-header"><h2 id="search-title">¿Qué quieres explorar?</h2><button class="icon-button" type="button" data-close-search aria-label="Cerrar búsqueda">{CLOSE}</button></div><div class="search-dialog-body"><label class="visually-hidden" for="site-search-input">Buscar en APAPSIF</label><input class="search-input" id="site-search-input" type="search" placeholder="Asociación, evaluación, recursos…" maxlength="160" autocomplete="off"><p class="search-hint">Pulsa <kbd>Esc</kbd> para cerrar. Abre con <kbd>Ctrl/⌘ K</kbd>. La búsqueda funciona en tu navegador.</p><div class="search-suggestions" aria-label="Búsquedas sugeridas"><button type="button" data-search-term="Afiliación">Afiliación</button><button type="button" data-search-term="Evaluación">Evaluación</button><button type="button" data-search-term="Informe pericial">Informe pericial</button></div><p class="result-count" id="search-status" role="status" aria-live="polite"></p><ul class="search-results" id="site-search-results"></ul></div></dialog><script id="search-data" type="application/json">{search_json}</script></body></html>'''
for page in PAGES:
    dest=DIST/'404.html' if page['path']=='/404.html' else DIST/page['path'].strip('/')/'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    rendered=document(page).replace('__HOSTING_PROVIDER__',ESC(CONFIG.get('hostingProvider','Sites')))
    if not PREVIEW:
        rendered=rendered.replace('Esta es una vista previa privada para revisión. El dominio apapsif.com todavía no está conectado. Los enlaces de contacto abren canales externos a este sitio.','Esta es la edición pública del sitio. Los enlaces de contacto abren canales externos a este sitio.')
    if BASE_PATH:
        rendered=re.sub(r'(href|src)="/(?!/)',lambda m:m.group(1)+'="'+BASE_PATH+'/',rendered)
    dest.write_text(rendered,encoding='utf-8')
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{ORIGIN}{p["path"]}</loc></url>\n' for p in PAGES if p['path']!='/404.html')+'</urlset>\n')
(DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n' if PREVIEW else f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n')
(DIST/'assets'/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#143d50"/><text x="32" y="49" text-anchor="middle" fill="#e8d1ab" font-family="Georgia,serif" font-size="51">Ψ</text></svg>')
headers='/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n'+('  X-Robots-Tag: noindex, nofollow, noarchive\n' if PREVIEW else '')+'\n/assets/*\n  Cache-Control: public, max-age=86400\n'
(DIST/'_headers').write_text(headers)
(DIST/'_redirects').write_text('/index.html / 301\n'+''.join(f'{p["path"]}index.html {p["path"]} 301\n' for p in PAGES if p['path'] not in ['/','/404.html']))
(ROOT/'content'/'pages.json').write_text(json.dumps([{k:v for k,v in p.items() if k not in ['body','schema']} for p in PAGES],ensure_ascii=False,indent=2))
print(f'Built {len(PAGES)} pages. Mode: {CONFIG["publicationMode"]}. Origin: {ORIGIN}')
